/**
 * Regression corpus of formulas typically found in university mathematics and
 * physics. Every entry is expressed as OMML, the same format Word stores in a
 * DOCX, so the tests exercise the real OMML -> MathML -> SVG image pipeline.
 *
 * The helpers intentionally stay close to the OMML vocabulary: a future Word
 * construct only needs a new helper, not a different input format.
 */
export interface FormulaCase { name: string; omml: string; category: string }
interface FormulaGroup { category: string; formulas: { name: string; omml: string }[] }

const esc = (s: string): string => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]!));
const r = (text: string, style?: 'p' | 'b' | 'i' | 'bi'): string =>
  `<m:r>${style ? `<m:rPr><m:sty m:val="${style}"/></m:rPr>` : ''}<m:t xml:space="preserve">${esc(text)}</m:t></m:r>`;
const seq = (...parts: string[]): string => parts.join('');
const f = (num: string, den: string, noBar = false): string =>
  `<m:f>${noBar ? '<m:fPr><m:type m:val="noBar"/></m:fPr>' : ''}<m:num>${num}</m:num><m:den>${den}</m:den></m:f>`;
const sup = (e: string, s: string): string => `<m:sSup><m:e>${e}</m:e><m:sup>${s}</m:sup></m:sSup>`;
const sub = (e: string, s: string): string => `<m:sSub><m:e>${e}</m:e><m:sub>${s}</m:sub></m:sSub>`;
const subsup = (e: string, s: string, p: string): string => `<m:sSubSup><m:e>${e}</m:e><m:sub>${s}</m:sub><m:sup>${p}</m:sup></m:sSubSup>`;
const sqrt = (e: string): string => `<m:rad><m:radPr><m:degHide m:val="1"/></m:radPr><m:deg/><m:e>${e}</m:e></m:rad>`;
const root = (deg: string, e: string): string => `<m:rad><m:deg>${deg}</m:deg><m:e>${e}</m:e></m:rad>`;
const del = (open: string, close: string, parts: string[], sep?: string): string =>
  `<m:d><m:dPr><m:begChr m:val="${esc(open)}"/>${sep ? `<m:sepChr m:val="${esc(sep)}"/>` : ''}<m:endChr m:val="${esc(close)}"/></m:dPr>${parts.map(p => `<m:e>${p}</m:e>`).join('')}</m:d>`;
const binom = (n: string, k: string): string => del('(', ')', [f(n, k, true)]);
const nary = (op: string, e: string, lower?: string, upper?: string, limLoc: 'subSup' | 'undOvr' = 'subSup'): string =>
  `<m:nary><m:naryPr><m:chr m:val="${esc(op)}"/><m:limLoc m:val="${limLoc}"/></m:naryPr>${lower ? `<m:sub>${lower}</m:sub>` : '<m:sub/>'}${upper ? `<m:sup>${upper}</m:sup>` : '<m:sup/>'}<m:e>${e}</m:e></m:nary>`;
const acc = (mark: string, e: string): string => `<m:acc><m:accPr><m:chr m:val="${esc(mark)}"/></m:accPr><m:e>${e}</m:e></m:acc>`;
const bar = (e: string, bottom = false): string => `<m:bar><m:barPr><m:pos m:val="${bottom ? 'bot' : 'top'}"/></m:barPr><m:e>${e}</m:e></m:bar>`;
const group = (chr: string, e: string, bottom = false): string =>
  `<m:groupChr><m:groupChrPr><m:chr m:val="${esc(chr)}"/><m:pos m:val="${bottom ? 'bot' : 'top'}"/></m:groupChrPr><m:e>${e}</m:e></m:groupChr>`;
const under = (e: string, lim: string): string => `<m:limLow><m:e>${e}</m:e><m:lim>${lim}</m:lim></m:limLow>`;
const mat = (rows: string[][], align?: 'left' | 'center' | 'right'): string =>
  `<m:m>${align ? `<m:mPr><m:mcs><m:mc><m:mcPr><m:count m:val="1"/><m:mcJc m:val="${align}"/></m:mcPr></m:mc></m:mcs></m:mPr>` : ''}${rows.map(row => `<m:mr>${row.map(cell => `<m:e>${cell}</m:e>`).join('')}</m:mr>`).join('')}</m:m>`;
const eqArr = (...rows: string[]): string => `<m:eqArr>${rows.map(row => `<m:e>${row}</m:e>`).join('')}</m:eqArr>`;
const fn = (name: string, arg: string): string => `<m:func><m:fName>${r(name, 'p')}</m:fName><m:e>${arg}</m:e></m:func>`;
const x = (): string => r('x');
const dx = (): string => r('dx');

const algebra: FormulaGroup = { category: '代数', formulas: [
  { name: '(a+b)^2', omml: seq(sup(del('(', ')', [seq(r('a'), r('+'), r('b'))]), r('2')), r('='), sup(r('a'), r('2')), r('+2ab+'), sup(r('b'), r('2'))) },
  { name: 'a^2-b^2', omml: seq(sup(r('a'), r('2')), r('−'), sup(r('b'), r('2')), r('='), del('(', ')', [seq(r('a'), r('−'), r('b'))]), del('(', ')', [seq(r('a'), r('+'), r('b'))])) },
  { name: 'a^3+b^3', omml: seq(sup(r('a'), r('3')), r('+'), sup(r('b'), r('3')), r('='), del('(', ')', [seq(r('a'), r('+'), r('b'))]), del('(', ')', [seq(sup(r('a'), r('2')), r('−ab+'), sup(r('b'), r('2')))])) },
  { name: 'a^3-b^3', omml: seq(sup(r('a'), r('3')), r('−'), sup(r('b'), r('3')), r('='), del('(', ')', [seq(r('a'), r('−'), r('b'))]), del('(', ')', [seq(sup(r('a'), r('2')), r('+ab+'), sup(r('b'), r('2')))])) },
  { name: '二项式定理', omml: seq(sup(del('(', ')', [seq(r('a'), r('+'), r('b'))]), r('n')), r('='), nary('∑', seq(binom(r('n'), r('k')), sup(r('a'), r('n−k')), sup(r('b'), r('k'))), r('k=0'), r('n'), 'undOvr')) },
  { name: '二项式系数和', omml: seq(nary('∑', binom(r('n'), r('k')), r('k=0'), r('n'), 'undOvr'), r('='), sup(r('2'), r('n'))) },
  { name: '一元二次求根公式', omml: seq(x(), r('='), f(seq(r('−b±'), sqrt(seq(sup(r('b'), r('2')), r('−4ac')))), r('2a'))) },
  { name: '韦达定理（和）', omml: seq(sub(r('x'), r('1')), r('+'), sub(r('x'), r('2')), r('=−'), f(r('b'), r('a'))) },
  { name: '韦达定理（积）', omml: seq(sub(r('x'), r('1')), sub(r('x'), r('2')), r('='), f(r('c'), r('a'))) },
  { name: '判别式', omml: seq(r('Δ='), sup(r('b'), r('2')), r('−4ac')) },
  { name: '对数换底', omml: seq(sub(r('log'), r('b')), r('x='), f(seq(r('ln x')), seq(r('ln b')))) },
  { name: '对数乘积', omml: seq(r('ln(xy)=ln x+ln y')) },
  { name: '对数商', omml: seq(r('ln'), del('(', ')', [f(r('x'), r('y'))]), r('=ln x−ln y')) },
  { name: '对数幂', omml: seq(r('ln'), sup(r('x'), r('n')), r('=n ln x')) },
  { name: '指数律', omml: seq(sup(r('a'), r('m')), sup(r('a'), r('n')), r('='), sup(r('a'), r('m+n'))) },
  { name: '根式有理化', omml: seq(f(r('1'), seq(sqrt(r('a')), r('+'), sqrt(r('b')))), r('='), f(seq(sqrt(r('a')), r('−'), sqrt(r('b'))), r('a−b'))) },
  { name: '复数模', omml: seq(del('|', '|', [r('z')]), r('='), sqrt(seq(sup(r('a'), r('2')), r('+'), sup(r('b'), r('2'))))) },
  { name: '复数除法', omml: seq(f(seq(sub(r('z'), r('1'))), seq(sub(r('z'), r('2')))), r('='), f(seq(sub(r('z'), r('1')), bar(sub(r('z'), r('2')))), sup(del('|', '|', [sub(r('z'), r('2'))]), r('2')))) },
  { name: '欧拉公式', omml: seq(sup(r('e'), r('iθ')), r('=cos θ+i sin θ')) },
  { name: '棣莫弗公式', omml: seq(sup(del('(', ')', [seq(r('cos θ+i sin θ'))]), r('n')), r('=cos nθ+i sin nθ')) },
  { name: '共轭复数', omml: seq(r('z'), bar(r('z')), r('='), sup(del('|', '|', [r('z')]), r('2'))) },
  { name: '等比数列求和', omml: seq(sub(r('S'), r('n')), r('='), f(seq(sub(r('a'), r('1')), del('(', ')', [seq(r('1−'), sup(r('q'), r('n')))])), r('1−q'))) },
  { name: '等差数列求和', omml: seq(sub(r('S'), r('n')), r('='), f(seq(r('n'), del('(', ')', [seq(sub(r('a'), r('1')), r('+'), sub(r('a'), r('n')))])), r('2'))) },
  { name: '排列数', omml: seq(subsup(r('P'), r('n'), r('k')), r('='), f(r('n!'), r('(n−k)!'))) },
  { name: '组合数', omml: seq(subsup(r('C'), r('n'), r('k')), r('='), f(r('n!'), seq(r('k!(n−k)!')))) },
  { name: '阶乘递推', omml: seq(r('n!=n(n−1)!')) },
  { name: '因式定理', omml: seq(r('f(x)=(x−a)q(x)+f(a)')) },
  { name: '余数定理', omml: seq(r('f(a)=0 ⇔ (x−a)|f(x)')) },
  { name: '(a+b+c)^2', omml: seq(sup(del('(', ')', [seq(r('a+b+c'))]), r('2')), r('='), sup(r('a'), r('2')), r('+'), sup(r('b'), r('2')), r('+'), sup(r('c'), r('2')), r('+2ab+2bc+2ca')) },
  { name: '指数方程', omml: seq(sup(r('a'), r('x')), r('=b ⇔ x='), sub(r('log'), r('a')), r('b')) },
  { name: '对数方程', omml: seq(r('ln x=b ⇔ x='), sup(r('e'), r('b'))) },
  { name: 'n 个 a 相加', omml: seq(group('⏟', r('a+a+⋯+a'), true), r('=na')) },
] };

const inequalities: FormulaGroup = { category: '不等式', formulas: [
  { name: 'AM-GM', omml: seq(f(seq(r('a+b')), r('2')), r('≥'), sqrt(r('ab'))) },
  { name: '加权 AM-GM', omml: seq(nary('∑', seq(sub(r('w'), r('i')), sub(r('x'), r('i'))), r('i=1'), r('n'), 'subSup'), r('≥'), nary('∏', sup(sub(r('x'), r('i')), sub(r('w'), r('i'))), r('i=1'), r('n'), 'subSup')) },
  { name: 'Cauchy-Schwarz', omml: seq(sup(del('(', ')', [nary('∑', seq(sub(r('a'), r('i')), sub(r('b'), r('i'))), r('i=1'), r('n'), 'subSup')]), r('2')), r('≤'), del('(', ')', [nary('∑', sup(sub(r('a'), r('i')), r('2')), r('i=1'), r('n'), 'subSup')]), del('(', ')', [nary('∑', sup(sub(r('b'), r('i')), r('2')), r('i=1'), r('n'), 'subSup')])) },
  { name: '三角不等式', omml: seq(del('|', '|', [seq(r('a+b'))]), r('≤'), del('|', '|', [r('a')]), r('+'), del('|', '|', [r('b')])) },
  { name: '反向三角不等式', omml: seq(del('|', '|', [seq(r('a−b'))]), r('≥'), del('|', '|', [seq(del('|', '|', [r('a')]), r('−'), del('|', '|', [r('b')]))])) },
  { name: 'Bernoulli 不等式', omml: seq(sup(del('(', ')', [seq(r('1+x'))]), r('n')), r('≥1+nx')) },
  { name: 'Chebyshev 不等式', omml: seq(f(r('1'), r('n')), nary('∑', seq(sub(r('a'), r('i')), sub(r('b'), r('i'))), r('i=1'), r('n'), 'subSup'), r('≥'), del('(', ')', [f(r('1'), r('n')), nary('∑', sub(r('a'), r('i')), r('i=1'), r('n'), 'subSup')]), del('(', ')', [f(r('1'), r('n')), nary('∑', sub(r('b'), r('i')), r('i=1'), r('n'), 'subSup')])) },
  { name: 'Jensen 不等式', omml: seq(r('φ'), del('(', ')', [f(seq(sub(r('x'), r('1')), r('+'), sub(r('x'), r('2'))), r('2'))]), r('≤'), f(seq(r('φ('), sub(r('x'), r('1')), r(')+φ('), sub(r('x'), r('2')), r(')')), r('2'))) },
  { name: 'Young 不等式', omml: seq(r('ab≤'), f(seq(sup(r('a'), r('p'))), r('p')), r('+'), f(seq(sup(r('b'), r('q'))), r('q'))) },
  { name: 'Hölder 不等式', omml: seq(nary('∑', seq(sub(r('a'), r('i')), sub(r('b'), r('i'))), r('i=1'), r('n'), 'subSup'), r('≤'), sup(del('(', ')', [nary('∑', sup(sub(r('a'), r('i')), r('p')), r('i=1'), r('n'), 'subSup')]), r('1/p')), sup(del('(', ')', [nary('∑', sup(sub(r('b'), r('i')), r('q')), r('i=1'), r('n'), 'subSup')]), r('1/q'))) },
  { name: 'Minkowski 不等式', omml: seq(sup(del('(', ')', [nary('∑', sup(del('|', '|', [seq(sub(r('a'), r('i')), r('+'), sub(r('b'), r('i')))]), r('p')), r('i=1'), r('n'), 'subSup')]), r('1/p')), r('≤'), sup(del('(', ')', [nary('∑', sup(del('|', '|', [sub(r('a'), r('i'))]), r('p')), r('i=1'), r('n'), 'subSup')]), r('1/p')), r('+'), sup(del('(', ')', [nary('∑', sup(del('|', '|', [sub(r('b'), r('i'))]), r('p')), r('i=1'), r('n'), 'subSup')]), r('1/p'))) },
  { name: 'a^2+b^2 ≥ 2ab', omml: seq(sup(r('a'), r('2')), r('+'), sup(r('b'), r('2')), r('≥2ab')) },
  { name: 'x+1/x ≥ 2', omml: seq(r('x+'), f(r('1'), r('x')), r('≥2')), },
  { name: '分式不等式', omml: seq(f(r('1'), r('x')), r('+'), f(r('1'), r('y')), r('≥'), f(r('4'), seq(r('x+y')))) },
  { name: 'ln(1+x) ≤ x', omml: seq(r('ln(1+x)≤x')) },
  { name: 'e^x ≥ 1+x', omml: seq(sup(r('e'), r('x')), r('≥1+x')) },
  { name: 'sin x ≤ x', omml: seq(r('sin x≤x')), },
  { name: '1-x ≤ e^{-x}', omml: seq(r('1−x≤'), sup(r('e'), r('−x'))) },
  { name: 'Nesbitt 不等式', omml: seq(f(r('a'), seq(r('b+c'))), r('+'), f(r('b'), seq(r('c+a'))), r('+'), f(r('c'), seq(r('a+b'))), r('≥'), f(r('3'), r('2'))) },
  { name: '绝对值三角不等式', omml: seq(del('|', '|', [seq(del('|', '|', [r('a')]), r('−'), del('|', '|', [r('b')]))]), r('≤'), del('|', '|', [seq(r('a−b'))])) },
  { name: '均值不等式链', omml: seq(f(r('2'), seq(f(r('1'), r('a')), r('+'), f(r('1'), r('b')))), r('≤'), sqrt(r('ab')), r('≤'), f(seq(r('a+b')), r('2')), r('≤'), sqrt(f(seq(sup(r('a'), r('2')), r('+'), sup(r('b'), r('2'))), r('2')))) },
] };

