const groups: FormulaGroup[] = [algebra, inequalities, limits, indefinite, definite, odes, probability, linearAlgebra, series, calculus, trig, physics];

export const formulaCategories: { category: string; formulas: FormulaCase[] }[] = groups.map(group => ({
  category: group.category,
  formulas: group.formulas.map(formula => ({ ...formula, category: group.category })),
}));

export const universityFormulas: FormulaCase[] = formulaCategories.flatMap(group => group.formulas);

/** Every formula is wrapped in a Word math paragraph by the tests. */
export const mathParagraph = (formula: FormulaCase): string => `<m:oMath>${formula.omml}</m:oMath>`;
